// Types for sol-telecom-2380.json, schemaVersion 1.0.0.
// Generated by colonization-sim.js (seed 1701). Fan work set in the Star Trek universe; not official.
//
// Usage (TypeScript, Node 20+ or a bundler):
//   import data from "./sol-telecom-2380.json" with { type: "json" };
//   import type { SolTelecomDataset } from "./sol-telecom-2380";
//   const dataset = data as SolTelecomDataset;
//
// All IDs are stable kebab-case strings, safe for URLs. Years are integers. Numbers are raw
// (no formatting); units are in the field names or in meta.units.

export type WorldId = string;
export type CompanyId = string;
export type RegionId = string;
export type SourceId = string;

export type SectorId = "science" | "commercial" | "industrial";
export type CompanyKind = "backbone" | "regional" | "gateway" | "specialist";
export type Environment = "radiation" | "cryogenic" | "solar" | "gas giant orbit";

export interface SolTelecomDataset {
  schemaVersion: "1.0.0";
  meta: Meta;
  regions: Region[];
  sectors: { id: SectorId; name: string }[];
  companyKinds: { id: CompanyKind; name: string; description: string }[];
  worlds: World[];
  companies: Company[];
  /** Everything that happened in the run, in year order. */
  events: SimEvent[];
}

export interface Meta {
  title: string;
  description: string;
  /** Random seed of the run this dataset was taken from. */
  seed: number;
  /** The year the snapshot describes (end of the run). */
  year: number;
  /** First simulated year; everything earlier comes from canon starting conditions. */
  simulationStart: number;
  /** Subspace radio speed as a multiple of light speed, used for latency. */
  subspaceSpeedC: number;
  units: Record<string, string>;
  sources: Source[];
}

export interface Source {
  id: SourceId;
  title: string;
  url: string;
}

export interface Region {
  id: RegionId;
  name: string;
  worldIds: WorldId[];
}

export interface World {
  id: WorldId;
  name: string;
  type: "planet" | "dwarf-planet" | "moon";
  /** The planet or dwarf planet a moon orbits; null for bodies orbiting the Sun. */
  parentId: WorldId | null;
  regionId: RegionId;
  physical: {
    /** True for the four giant planets (no solid surface). */
    gaseous: boolean;
    radiusKm: number;
    massKg: number;
    surfaceGravityMs2: number;
    /** Chemical symbols, most important first. */
    mainElements: string[];
    /** Semi-major axis around the Sun. A moon carries its parent's value. */
    distanceFromSunAu: number;
    /** Semi-major axis around the parent; null for bodies orbiting the Sun. */
    orbitRadiusKm: number | null;
    /** One orbit of the parent (moons) or of the Sun (planets, dwarf planets). */
    orbitalPeriodDays: number;
    orbitalSpeedKmS: number;
  };
  history: {
    /** Year the first relay constellation went up. */
    constellationEstablished: number | null;
    /** "conventional" = light-speed relays built before subspace (later converted). */
    constellationStartedAs: "conventional" | "subspace" | null;
    subspaceSince: number | null;
    /** Year the colony was founded; null for Earth (see homeworld). */
    colonized: number | null;
    homeworld: boolean;
    /** Year the population passed one million, or null if it never did by meta.year. */
    passedOneMillion: number | null;
  };
  /** People living there in meta.year; null for Earth (not modelled). */
  population: number | null;
  /** Population at snapshot years, keyed by year as a string; null for Earth. */
  populationHistory: Record<string, number> | null;
  communications: {
    /** One-way subspace delay to Earth, closest and farthest approach. */
    subspaceLatencyToEarthMs: { min: number; max: number };
    /** Days between solar conjunctions with Earth (Sun between the two); null for Earth and the Moon. */
    solarConjunctionWithEarthEveryDays: number | null;
  };
  /** Facts from Star Trek canon about this world, if any. */
  canon: { year: number | null; text: string; sourceId: SourceId | null }[];
  /** Every brand selling service here in meta.year, including divisions of larger companies. */
  providerIds: CompanyId[];
}

export interface Company {
  id: CompanyId;
  name: string;
  kind: CompanyKind;
  kindLabel: string;
  sectors: SectorId[];
  /** Harsh environment the network is built for, if any. */
  environment: Environment | null;
  /** One-line description of what the company does. */
  focus: string;
  headquartersWorldId: WorldId;
  regionId: RegionId;
  founded: number;
  /** The company it was spun off from. */
  parentId: CompanyId | null;
  origin: "pre-subspace network" | "spin-off" | "startup";
  /**
   * active   = independent and trading.
   * division = bought, but still trading under its own name (see ownerId).
   * merged   = bought and folded into the buyer's network; no longer sold.
   */
  status: "active" | "division" | "merged";
  /** For a division or merged company: the independent company that ultimately owns it now. */
  ownerId: CompanyId | null;
  /** The company that bought it (may itself have been bought since). */
  acquiredById: CompanyId | null;
  acquiredYear: number | null;
  /** Worlds where this brand is sold in meta.year. Empty for merged companies. */
  servesWorldIds: WorldId[];
  /** Brands this company owns that still trade under their own names. */
  divisionIds: CompanyId[];
}

export type SimEventType =
  | "conventional-constellation"
  | "subspace-constellation"
  | "constellation-converted"
  | "colonized"
  | "population-one-million"
  | "company-founded"
  | "company-acquired";

export interface SimEvent {
  year: number;
  type: SimEventType;
  worldId: WorldId;
  /** Free text from the simulation, e.g. "relay hub for Io" or "from Utopia Planitia". */
  detail: string | null;
  /** Set on company-founded and company-acquired. */
  companyId?: CompanyId;
  /** Set on company-acquired. */
  buyerId?: CompanyId;
}
